input.sparql:
SELECT ?zone ?label ?sensor ?sensorClass ?hasTs WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  FILTER (CONTAINS(?label, "DataCenter_bot_ZN_6"))
  ?zone brick:hasPoint ?sensor .
  ?sensor a ?sensorClass .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?hasTs . }
}

SELECT ?zone ?label WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  FILTER (CONTAINS(?label, "DataCenter_bot_ZN_6"))
}

SELECT ?x ?cls ?label WHERE {
  OPTIONAL { ?x a ?cls . }
  ?x rdfs:label ?label .
  FILTER (CONTAINS(?label, "DataCenter_bot_ZN_6"))
}

SELECT ?sensor ?cls ?label ?ts WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07> ?rel ?sensor .
  OPTIONAL { ?sensor a ?cls . }
  OPTIONAL { ?sensor rdfs:label ?label . }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?ts . }
}

